// Kohinoor Tiwari — portfolio script
(function(){
  var splash=document.getElementById('splash');
  document.body.style.overflow='hidden';
  setTimeout(function(){splash.classList.add('out');document.body.style.overflow='';},2300);
  
  var CV="";
  function cvBytes(){var b=atob(CV),u=new Uint8Array(b.length);for(var i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u}
  var msg=document.getElementById('cvmsg');
  function plainSave(){var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([cvBytes()],{type:'application/pdf'}));a.download='Kohinoor_Tiwari_CV.pdf';document.body.appendChild(a);a.click();a.remove();if(msg)msg.textContent='CV downloaded.'}
  document.querySelectorAll('.cv').forEach(function(btn){btn.addEventListener('click',function(){
    var u=(window.claude&&claude.use)?claude.use('downloads'):Promise.resolve(null);
    u.then(function(d){
      if(!d){plainSave();return}
      return d.save({filename:'Kohinoor_Tiwari_CV.pdf',data:new Blob([cvBytes()],{type:'application/pdf'})}).then(function(){if(msg)msg.textContent='CV saved.'}).catch(function(e){if(msg&&e&&e.code!=='declined')msg.textContent='Could not save the CV.'});
    }).catch(plainSave);
  })});
  // photo: set PHOTO to a data URI to show it
  var PHOTO="data:image/jpeg;base64,";
  if(PHOTO){var im=document.getElementById('photo');im.src=PHOTO;im.hidden=false;document.getElementById('ph').style.display='none'}
  var nav=document.getElementById('nav');
  addEventListener('scroll',function(){nav.classList.toggle('scrolled',scrollY>10)},{passive:true});
  var els=document.querySelectorAll('.reveal');
  if('IntersectionObserver' in window){
    var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}})},{threshold:.08});
    els.forEach(function(el){io.observe(el)});
  }else{els.forEach(function(el){el.classList.add('in')})}
})();
